problems.solutionCode:
#include <stdio.h>

static long long power(long long base, int exp) {
    long long res = 1;
    for (int i = 0; i < exp; i++) res *= base;
    return res;
}

int main() {
    long long n;
    if (scanf("%lld", &n) != 1) return 0;
    long long temp = n;
    int digits = 0;
    while (temp > 0) {
        digits++;
        temp /= 10;
    }
    temp = n;
    long long sum = 0;
    while (temp > 0) {
        int d = temp % 10;
        sum += power(d, digits);
        temp /= 10;
    }
    if (sum == n) {
        printf("ARMSTRONG\n");
    } else {
        printf("NOT ARMSTRONG\n");
    }
    return 0;
}

