void hanoi(int n, char from, char to, char aux, long long *move_count) {
    if (n == 0) return;
    hanoi(n - 1, from, aux, to, move_count);
    printf("Move disk %d from %c to %c\n", n, from, to);
    (*move_count)++;
    hanoi(n - 1, aux, to, from, move_count);
}

int main() {
    int n;
    if (scanf("%d", &n) != 1) return 0;
    long long count = 0;
    hanoi(n, 'A', 'C', 'B', &count);
