#include <stdio.h>
#include <ctype.h>

int countVowels(const char *str) {
    int count = 0;
    const char *ptr = str;
    while (*ptr != '\0') {
        char ch = tolower((unsigned char)*ptr);
        if (ch == 'a' || ch == 'e' || ch == 'i' || ch == 'o' || ch == 'u') {
            count++;
        }
        ptr++;
    }
    return count;
}

int main() {
    char str[1024];
    if (scanf("%1023s", str) != 1) return 0;
    printf("%d\n", countVowels(str));
    return 0;
}

