problems.solutionCode:
#include <stdio.h>

int main() {
    int r, c;
    if (scanf("%d %d", &r, &c) != 2 || r <= 0 || c <= 0) return 0;
    static long long mat[105][105];
    for (int i = 0; i < r; i++) {
        for (int j = 0; j < c; j++) {
            if (scanf("%lld", &mat[i][j]) != 1) return 0;
        }
    }
    int top = 0, bottom = r - 1, left = 0, right = c - 1;
    int first = 1;
    while (top <= bottom && left <= right) {
        // Traverse Right
        for (int j = left; j <= right; j++) {
            if (!first) printf(" ");
            printf("%lld", mat[top][j]);
            first = 0;
        }
        top++;

        // Traverse Down
        for (int i = top; i <= bottom; i++) {
            if (!first) printf(" ");
            printf("%lld", mat[i][right]);
            first = 0;
        }
        right--;

        // Traverse Left
        if (top <= bottom) {
            for (int j = right; j >= left; j--) {
                if (!first) printf(" ");
                printf("%lld", mat[bottom][j]);
                first = 0;
            }
            bottom--;
        }

        // Traverse Up
        if (left <= right) {
            for (int i = bottom; i >= top; i--) {
                if (!first) printf(" ");
                printf("%lld", mat[i][left]);
                first = 0;
            }
            left++;
        }
    }
    printf("\n");
    return 0;
}

