    if (fabs(sum.imag) < 1e-9) sum.imag = 0.0;
    if (sum.imag >= 0.0) {
        printf("%.2f + %.2fi\n", sum.real, sum.imag);
    } else {
        printf("%.2f - %.2fi\n", sum.real, -sum.imag);
    }
    return 0;
}

