problems.solutionCode:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    int *data;
    int top;
    int capacity;
} DynamicStack;

void push(DynamicStack *s, int val) {
    if (s->top + 1 >= s->capacity) {
        s->capacity *= 2;
        s->data = (int *)realloc(s->data, s->capacity * sizeof(int));
    }
    s->data[++(s->top)] = val;
}

void pop(DynamicStack *s) {
    if (s->top < 0) {
        printf("UNDERFLOW\n");
    } else {
        printf("%d\n", s->data[(s->top)--]);
    }
}

void peek(DynamicStack *s) {
    if (s->top < 0) {
        printf("EMPTY\n");
    } else {
        printf("%d\n", s->data[s->top]);
    }
}

int main() {
    int q;
    if (scanf("%d", &q) != 1) return 0;
    DynamicStack s;
    s.capacity = 2;
    s.top = -1;
    s.data = (int *)malloc(s.capacity * sizeof(int));

    char cmd[16];
    while (q--) {
        if (scanf("%15s", cmd) != 1) break;
        if (strcmp(cmd, "PUSH") == 0) {
            int val;
            scanf("%d", &val);
            push(&s, val);
        } else if (strcmp(cmd, "POP") == 0) {
            pop(&s);
        } else if (strcmp(cmd, "PEEK") == 0) {
            peek(&s);
        }
    }
    free(s.data);
    return 0;
}

