problems.solutionCode:
#include <stdio.h>
#include <stdlib.h>

struct Node {
    int val;
    int index;
    struct Node *next;
};

int main() {
    int n, pos;
    if (scanf("%d %d", &n, &pos) != 2) return 0;
    struct Node **nodes = (struct Node **)malloc(n * sizeof(struct Node *));
    for (int i = 0; i < n; i++) {
        nodes[i] = (struct Node *)malloc(sizeof(struct Node));
        scanf("%d", &nodes[i]->val);
        nodes[i]->index = i;
        nodes[i]->next = NULL;
        if (i > 0) nodes[i - 1]->next = nodes[i];
    }
    if (pos >= 0 && pos < n) {
        nodes[n - 1]->next = nodes[pos];
    }

    struct Node *slow = nodes[0];
    struct Node *fast = nodes[0];
    int hasCycle = 0;

    while (fast && fast->next) {
        slow = slow->next;
        fast = fast->next->next;
        if (slow == fast) {
            hasCycle = 1;
            break;
        }
    }

    if (!hasCycle) {
        printf("NO CYCLE\n");
    } else {
        // Find cycle start
        struct Node *ptr1 = nodes[0];
        struct Node *ptr2 = slow;
        while (ptr1 != ptr2) {
            ptr1 = ptr1->next;
            ptr2 = ptr2->next;
        }
        printf("CYCLE DETECTED AT NODE %d\n", ptr1->index);
    }

    // Clean up
    if (pos >= 0 && pos < n) nodes[n - 1]->next = NULL;
    for (int i = 0; i < n; i++) free(nodes[i]);
    free(nodes);
    return 0;
}

