problems.solutionCode:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    char *buffer;
    size_t length;
    size_t capacity;
} StringBuilder;

void sb_init(StringBuilder *sb) {
    sb->capacity = 4;
    sb->length = 0;
    sb->buffer = (char *)malloc(sb->capacity * sizeof(char));
    sb->buffer[0] = '\0';
}

void sb_append(StringBuilder *sb, const char *str) {
    size_t addLen = strlen(str);
    while (sb->length + addLen + 1 > sb->capacity) {
        sb->capacity *= 2;
        sb->buffer = (char *)realloc(sb->buffer, sb->capacity * sizeof(char));
    }
    memcpy(sb->buffer + sb->length, str, addLen);
    sb->length += addLen;
    sb->buffer[sb->length] = '\0';
}

int main() {
    int q;
    if (scanf("%d", &q) != 1) return 0;
    StringBuilder sb;
    sb_init(&sb);
    for (int i = 0; i < q; i++) {
        char word[128];
        if (scanf("%127s", word) == 1) {
            sb_append(&sb, word);
        }
    }
    printf("%s\n", sb.buffer);
    printf("LENGTH: %zu CAPACITY: %zu\n", sb.length, sb.capacity);
    free(sb.buffer);
    return 0;
}

